'use client';
import { useState } from 'react';
import Link from 'next/link';
import { 
  LayoutDashboard, Building2, Stethoscope, Calendar, 
  Users, Tag, ShieldCheck, LogOut, Menu 
} from 'lucide-react';
import { Outfit } from 'next/font/google';

const outfit = Outfit({ subsets: ['latin'] });

export default function AdminLayout({ children }) {
  const [sidebarOpen, setSidebarOpen] = useState(true);

  return (
    <div className={`admin-root ${outfit.className}`} style={{ display: 'flex', minHeight: '100vh', background: '#0f172a', color: '#fff' }}>
      
      {/* Sidebar */}
      <aside style={{ 
        width: sidebarOpen ? '260px' : '80px', 
        background: 'rgba(30, 41, 59, 0.5)', 
        borderRight: '1px solid rgba(255,255,255,0.05)', 
        transition: 'width 0.3s',
        display: 'flex',
        flexDirection: 'column'
      }}>
        <div style={{ padding: '1.5rem', display: 'flex', alignItems: 'center', gap: '1rem', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
           <div style={{ background: 'var(--primary)', padding: '6px', borderRadius: '8px' }}>
              <ShieldCheck size={24} color="#fff" />
           </div>
           {sidebarOpen && <span style={{ fontWeight: 'bold', fontSize: '1.2rem' }}>Suvidha Admin</span>}
        </div>

        <nav style={{ flex: 1, padding: '1rem', display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
           <NavItem icon={<LayoutDashboard size={20} />} label="Overview" href="/admin" isOpen={sidebarOpen} />
           <NavItem icon={<Building2 size={20} />} label="Hospitals" href="/admin/hospitals" isOpen={sidebarOpen} />
           <NavItem icon={<Stethoscope size={20} />} label="Services" href="/admin/services" isOpen={sidebarOpen} />
           <NavItem icon={<Calendar size={20} />} label="Bookings" href="/admin/bookings" isOpen={sidebarOpen} />
           <NavItem icon={<Tag size={20} />} label="Offers" href="/admin/offers" isOpen={sidebarOpen} />
           <NavItem icon={<Users size={20} />} label="Users" href="/admin/users" isOpen={sidebarOpen} />
        </nav>

        <div style={{ padding: '1rem', borderTop: '1px solid rgba(255,255,255,0.05)' }}>
           <button style={{ 
              display: 'flex', alignItems: 'center', gap: '1rem', 
              background: 'transparent', border: 'none', color: '#ef4444', 
              padding: '0.8rem', borderRadius: '8px', cursor: 'pointer',
              width: '100%'
           }}>
              <LogOut size={20} />
              {sidebarOpen && <span>Logout</span>}
           </button>
        </div>
      </aside>

      {/* Main Content */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
        <header className="glass" style={{ 
           padding: '1rem 2rem', 
           display: 'flex', justifyContent: 'space-between', alignItems: 'center',
           borderRadius: 0, borderBottom: '1px solid rgba(255,255,255,0.05)'
        }}>
           <button onClick={() => setSidebarOpen(!sidebarOpen)} style={{ background: 'transparent', border: 'none', color: '#fff', cursor: 'pointer' }}>
              <Menu size={24} />
           </button>
           <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
              <div style={{ width: '35px', height: '35px', borderRadius: '50%', background: 'var(--primary)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold' }}>
                 A
              </div>
              <span>Super Admin</span>
           </div>
        </header>
        
        <main style={{ padding: '2rem', flex: 1, overflowY: 'auto' }}>
           {children}
        </main>
      </div>

    </div>
  );
}

function NavItem({ icon, label, href, isOpen }) {
  return (
    <Link href={href} style={{ 
       display: 'flex', alignItems: 'center', gap: '1rem', 
       padding: '0.8rem 1rem', borderRadius: '8px', 
       color: 'var(--text-muted)', 
       transition: 'all 0.2s',
       textDecoration: 'none'
    }}
    className="admin-nav-item"
    >
       {icon}
       {isOpen && <span>{label}</span>}
       <style jsx>{`
         .admin-nav-item:hover {
            background: rgba(255,255,255,0.05);
            color: #fff !important;
         }
       `}</style>
    </Link>
  );
}
